grant select(id,product_id,storage_path,alt_text,sort_order) on public.product_images to anon,authenticated;
create policy product_images_public_catalog_read on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p join public.stores s on s.id=p.store_id where p.id=product_images.product_id and p.status='published' and s.store_status='active' and s.verification_status='verified' and s.online_sales_enabled=true));
create policy pluits_store_media_public_product_read on storage.objects for select to anon,authenticated using(bucket_id='pluits-store-media' and exists(select 1 from public.product_images pi join public.products p on p.id=pi.product_id join public.stores s on s.id=p.store_id where pi.storage_path=objects.name and p.status='published' and s.store_status='active' and s.verification_status='verified' and s.online_sales_enabled=true));
